// Limiter is a concurrency-safe token-bucket rate limiter.
// Tokens refill continuously at rate tokens per second, up to burst capacity.
type Limiter struct {
	mu        sync.Mutex
	clock     Clock
	rate      float64 // tokens per second
	burst     float64 // bucket capacity
	tokens    float64
	lastRefil time.Time
}

var ErrInvalidParams = errors.New("ratelimit: rate and burst must be > 0")

// New returns a Limiter with the given refill rate (tokens/sec) and burst
// capacity, starting full. clock must be non-nil.
func New(rate float64, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidParams
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		clock:     clock,
		rate:      rate,
		burst:     burst,
		tokens:    burst,
		lastRefil: clock.Now(),
	}, nil
}

// AllowN reports whether n tokens may be consumed now; if so, they are
// consumed. n must be non-negative; a negative n returns false.
func (l *Limiter) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastRefil).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastRefil = now
	}
	if l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }
