package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	burst    int
	rate     float64 // tokens per second
	clock    Clock
	maxLeeway time.Duration // reserved for future use; zero means unused
}

var (
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). If clock is nil, the real clock is used.
func New(burst int, rate float64, clock Clock) (*Limiter, error) {
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		tokens: float64(burst),
		last:   now,
		burst:  burst,
		rate:   rate,
		clock:  clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at the current time,
// consuming them if so. n must be positive; a non-positive n returns false.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > float64(l.burst) {
		t = float64(l.burst)
	}
	return t
}
